data.pageSchema:
{
  "renderer": "page",
  "body": [
    {
      "renderer": "form",
      "controls": [
        {
          "renderer": "input",
          "name": "username",
          "placeholder": "姓名",
          "type": "text",
          "rules": []
        },
        {
          "renderer": "datepicker",
          "name": "createdAt",
          "readonly": false,
          "rules": [],
          "placeholder": "创建时间"
        },
        {
          "renderer": "action",
          "text": "搜索",
          "actionType": "submit",
          "body": {}
        },
        {
          "renderer": "datepicker",
          "name": "updatedAt",
          "readonly": false,
          "rules": [],
          "placeholder": "更新时间"
        }
      ],
      "submitType": "target",
      "inline": true,
      "target": "UserTable"
    },
    {
      "renderer": "table",
      "name": "UserTable",
      "maxHeight": 570,
      "showExport": true,
      "initApi": {
        "url": "/api/users",
        "method": "get",
        "params": {
          "name": "${username}"
        }
      },
      "initData": {
        "username": ""
      },
      "columns": [
        {
          "name": "username",
          "label": "姓名",
          "visibleOn": "",
          "body": []
        },
        {
          "name": "nickname",
          "label": "昵称",
          "body": []
        },
        {
          "name": "email",
          "label": "邮件",
          "body": []
        },
        {
          "name": "avatar",
          "label": "头像",
          "body": []
        },
        {
          "name": "createdAt",
          "label": "创建时间",
          "sortable": true,
          "body": []
        },
        {
          "name": "updatedAt",
          "label": "更新时间",
          "sortable": true,
          "body": []
        },
        {
          "label": "操作集合",
          "body": [
            {
              "renderer": "action",
              "text": "编辑角色",
              "size": "small",
              "plain": true,
              "actionType": "dialog",
              "actionApi": {
                "url": "/api/user?uid=${uid}",
                "method": "delete"
              },
              "confirmTitle": "你删除吗？",
              "reload": "usertable",
              "body": {
                "body": [
                  {
                    "renderer": "form",
                    "controls": [
                      {
                        "renderer": "list",
                        "initApi": {
                          "url": "/api/roles?type=list",
                          "method": "get",
                          "cached": false,
                          "params": {}
                        },
                        "name": "roles",
                        "label": "角色",
                        "options": [],
                        "rules": [],
                        "optionConfig": {
                          "text": "name",
                          "value": "id"
                        },
                        "body": [
                          {
                            "renderer": "html",
                            "html": "<div class=\"role_list_text\"><%=data.name%></div>",
                            "inline": true
                          }
                        ]
                      }
                    ],
                    "name": "UpdateUser",
                    "initApi": {
                      "url": "/api/user?id=${id}",
                      "method": "get",
                      "cached": false,
                      "params": {}
                    },
                    "actionApi": {
                      "url": "/api/user/${id}",
                      "method": "put",
                      "params": {
                        "*": "*"
                      }
                    },
                    "reload": "UserTable"
                  }
                ],
                "footer": [
                  {
                    "renderer": "action",
                    "text": "确定",
                    "actionType": "trigger",
                    "triggered": "UpdateUser",
                    "body": {}
                  }
                ]
              }
            },
            {
              "renderer": "action",
              "text": "删除",
              "type": "warning",
              "size": "small",
              "actionType": "ajax",
              "actionApi": {
                "url": "/api/${namespace}/${id}",
                "method": "delete",
                "params": {}
              },
              "reload": "UserTable",
              "body": {}
            }
          ]
        }
      ],
      "actions": [
        {
          "renderer": "action",
          "text": "添加用户",
          "size": "small",
          "actionType": "dialog",
          "body": {
            "body": [
              {
                "renderer": "form",
                "controls": [
                  {
                    "renderer": "input",
                    "name": "username",
                    "label": "用户名",
                    "requiredOn": "1",
                    "placeholder": "请输入",
                    "type": "text",
                    "rules": []
                  },
                  {
                    "renderer": "input",
                    "name": "email",
                    "label": "邮件",
                    "placeholder": "请输入",
                    "type": "text",
                    "rules": [
                      {
                        "type": "email"
                      }
                    ],
                    "requiredOn": "1"
                  },
                  {
                    "renderer": "list",
                    "initApi": {
                      "url": "/api/roles?type=list",
                      "method": "get",
                      "cached": false,
                      "params": {}
                    },
                    "name": "roles",
                    "label": "角色",
                    "options": [],
                    "rules": [],
                    "optionConfig": {
                      "text": "name",
                      "value": "id"
                    },
                    "body": [
                      {
                        "renderer": "html",
                        "html": "<div class=\"role_list_text\"><%=data.name%></div>",
                        "inline": true
                      }
                    ],
                    "requiredOn": "1"
                  },
                  {
                    "renderer": "computed",
                    "name": "invited",
                    "exp": "1"
                  }
                ],
                "name": "CreateForm",
                "actionApi": {
                  "url": "/api/user/invited",
                  "method": "post",
                  "params": {
                    "*": "*"
                  }
                },
                "visibleOn": "$id != ''"
              },
              {
                "renderer": "action",
                "text": "请<%=$.username%>补充用户信息",
                "isText": true,
                "tag": "a",
                "actionType": "copy",
                "content": "1234",
                "body": {},
                "visibleOn": "$.id == ''"
              }
            ],
            "footer": [
              {
                "renderer": "action",
                "text": "提交",
                "actionType": "trigger",
                "triggered": "CreateForm",
                "body": {}
              }
            ]
          },
          "icon": "Plus"
        }
      ],
      "height": 490,
      "showDynamicColumn": true
    }
  ],
  "mergeUrlQuery": true,
  "innerStyle": ".role_list_text {\n  padding: 14px 28px;\n}"
}
